function deleteChronicle(id){
  const row=state.chronicles.find(item=>item.id===id);if(!row)return;
  const normalizedTitle=value=>String(value||"").trim().replace(/\s+/g," ").toLowerCase();
  const duplicate=state.chronicles.find(item=>item.id!==row.id&&item.characterId===row.characterId&&normalizedTitle(item.title)===normalizedTitle(row.title)&&(!row.datePlayed||!item.datePlayed||item.datePlayed===row.datePlayed));
  const linkedSessions=state.sessionHistory.filter(item=>item.linkedChronicleId===row.id);
  const linkedPurchases=state.purchases.filter(item=>item.chronicleId===row.id);
  const itemizedCount=linkedPurchases.filter(item=>item.itemized).length;
  const details=[`Delete "${row.title||"Untitled chronicle"}"?`,`This removes ${Number(row.xpEarned)||0} XP, ${money(row.gpGained)} gained, ${money(chronicleSpend(row))} spent, and the chronicle's reputation.`];
  if(itemizedCount)details.push(`${itemizedCount} linked itemized purchase(s) will be kept, detached, and deducted separately.`);
  if(linkedPurchases.length-itemizedCount)details.push(`${linkedPurchases.length-itemizedCount} other linked purchase note(s) will be kept and unlinked.`);
  if(linkedSessions.length)details.push(duplicate?"Its Paizo session link(s) will move to the other matching chronicle.":"Its Paizo session link(s) will be cleared, leaving those sessions available to match again.");
  if(row.fileKey)details.push(duplicate&&!duplicate.fileKey?"The scan will be moved to the other matching chronicle.":"The scan will remain in private storage.");
  if(!window.confirm(details.join("\n\n")))return;
  if(duplicate&&row.fileKey&&!duplicate.fileKey){duplicate.fileKey=row.fileKey;duplicate.fileName=row.fileName||"";duplicate.mimeType=row.mimeType||"";}
  for(const session of linkedSessions)session.linkedChronicleId=duplicate?.id||"";
  for(const purchase of linkedPurchases){purchase.chronicleId="";if(purchase.itemized||purchase.countsTowardChronicleSpend){purchase.itemized=false;purchase.countsTowardChronicleSpend=false;purchase.affectsBalance=true;purchase.notes=[purchase.notes,`Retained as a separate purchase after deleting "${row.title||"Untitled chronicle"}".`].filter(Boolean).join(" ");}}
  state.chronicles=state.chronicles.filter(item=>item.id!==id);
  saveState();render();
}

function boonCard(boon){const remaining=Math.max(0,Number(boon.uses)||0-(Number(boon.used)||0));const limited=boon.useType==="limited";const left=Math.max(0,(Number(boon.uses)||0)-(Number(boon.used)||0));return `<article class="boon-item"><div class="boon-top"><strong>${esc(boon.name)}</strong><span class="boon-type">${limited?`${left}/${Number(boon.uses)||1} uses left`:"Permanent"}</span></div>${boon.description?`<p class="boon-description">${esc(boon.description)}</p>`:""}<div class="boon-footer"><span>${esc(boon.source||"Source not recorded")}${limited&&boon.resetCondition?` · resets ${esc(boon.resetCondition)}`:""}</span>${limited?`<span class="boon-actions"><button class="small-button" data-reset-boon="${esc(boon.id)}">Reset</button><button class="small-button" data-use-boon="${esc(boon.id)}" ${left<=0?"disabled":""}>Use</button></span>`:""}</div></article>`;}
function renderChronicles(){const visibleIds=new Set(activeCharacters().map(character=>character.id));const rows=state.chronicles.filter(row=>visibleIds.has(row.characterId)).sort((a,b)=>(b.datePlayed||"").localeCompare(a.datePlayed||""));app.innerHTML=`<div class="page-intro"><div><p class="eyebrow">${activeSociety==="starfinder"?"STARFINDER SOCIETY":"PFS 2E"} · RECORDS</p><h1>Chronicle archive</h1><p>Each confirmed sheet remains attached to its reward entry.</p></div><button class="button button-primary" id="new-chronicle">＋ Record chronicle</button></div><div class="storage-callout"><span>●</span><span><b>${cloudUser?"Private cloud sync":"Files stay on this device"}:</b> ${cloudUser?"Chronicle scans and portraits use private Supabase storage when configured, then download to this browser when opened.":"Ledger data syncs after sign-in; chronicle scans and portraits stay in this browser until you sign in."}</span></div><section class="panel"><div class="panel-title"><h2>All chronicles</h2><span>${rows.length} records</span></div><div class="record-list">${rows.length?rows.map(row=>{const c=state.characters.find(x=>x.id===row.characterId);return `<div class="record-item"><span class="record-icon">▤</span><div class="record-copy"><strong>${esc(row.title||"Untitled chronicle")}</strong><span>${esc(c?.name||"Character removed")} · ${fmtDate(row.datePlayed)} · ${esc(chronicleTypeName(row.sheetType))}</span><button class="link-button" data-chronicle="${esc(row.id)}" data-attachment="${esc(row.fileKey||"")}" data-filename="${esc(row.fileName||"")}">${row.fileKey?"Open sheet":"Attach scan"}</button><button class="link-button delete-chronicle-button" data-delete-chronicle="${esc(row.id)}">Delete</button></div><div class="record-delta">+${Number(row.xpEarned)||0} XP<br>${money((Number(row.gpGained)||0)-(Number(row.gpSpent)||0))}</div></div>`}).join(""):`<div class="list-empty">Confirmed chronicles will appear here.</div>`}</div></section>`;document.querySelector("#new-chronicle").addEventListener("click",()=>openChronicleDialog());document.querySelectorAll("[data-chronicle]").forEach(button=>button.addEventListener("click",()=>{const row=state.chronicles.find(item=>item.id===button.dataset.chronicle);if(row?.fileKey)openAttachment(row.fileKey,row.fileName);else if(row)openChronicleDialog(row.characterId,"",row.id);}));document.querySelectorAll("[data-delete-chronicle]").forEach(button=>button.addEventListener("click",()=>deleteChronicle(button.dataset.deleteChronicle)));}
function openCharacter(id){selectedCharacterId=id;currentView="detail";history.pushState({societyLedgerView:"character",characterId:id},"");render();}
window.addEventListener("popstate",event=>{if(currentView==="detail"){currentView="home";selectedCharacterId=null;render();return;}if(event.state?.societyLedgerView==="character"&&state.characters.some(row=>row.id===event.state.characterId&&societyOf(row)===activeSociety)){selectedCharacterId=event.state.characterId;currentView="detail";render();}});
function structuredReputation(data){const changes={};for(let index=1;index<=3;index++){const faction=String(data.get(`repFaction${index}`)||"");const amount=Number(data.get(`repAmount${index}`))||0;if(faction&&amount)changes[faction]=amount;}return changes;}
function legacyReputation(row){if(row.reputationChanges)return Object.entries(row.reputationChanges);return String(row.reputation||"").split(/[;\n]+/).map(parseRep).filter(item=>item.name).map(item=>[item.name,item.amount]);}
function syncRepFactionOptions(){const selects=[...document.querySelectorAll(".rep-faction")];for(const select of selects){const elsewhere=new Set(selects.filter(other=>other!==select).map(other=>other.value).filter(Boolean));for(const option of select.options)option.disabled=Boolean(option.value&&elsewhere.has(option.value));}}
document.querySelectorAll(".rep-faction").forEach(select=>select.addEventListener("change",syncRepFactionOptions));
function updateSocietyFields(society=activeSociety){const starfinder=society==="starfinder",characterFaction=document.querySelector("#character-faction-field");if(characterFaction)characterFaction.hidden=starfinder;const reputation=document.querySelector("#chronicle-reputation-field");if(reputation)reputation.hidden=starfinder;for(const [id,label] of [["starting-currency-label",starfinder?"Starting credits":"Starting gold (gp)"],["chronicle-gained-label",starfinder?"Credits gained":"Gold gained (gp)"],["chronicle-spent-label",starfinder?"Credits spent":"Gold spent (gp)"],["chronicle-adjustment-label",starfinder?"Credit adjustment":"Gold adjustment (gp)"],["purchase-cost-label",starfinder?"Cost (credits)":"Cost (gp)"]]){const element=document.querySelector(`#${id}`);if(element)element.textContent=label;}for(const input of [document.querySelector("#character-form [name=gp]"),document.querySelector("#chronicle-form [name=gpGained]"),document.querySelector("#chronicle-form [name=gpSpent]"),document.querySelector("#chronicle-form [name=gpAdjustment]"),document.querySelector("#purchase-form [name=cost]")])if(input)input.step=starfinder?"1":"0.01";const itemized=document.querySelector("#purchase-itemized-label");if(itemized)itemized.textContent=starfinder?"Count this item within the associated chronicle’s credits spent (don’t deduct twice)":"Count this item within the associated chronicle’s gold spent (don’t deduct twice)";const eyebrow=document.querySelector("#chronicle-dialog-eyebrow");if(eyebrow)eyebrow.textContent=starfinder?"SFS 2E · CHRONICLE INTAKE":"PFS 2E · CHRONICLE INTAKE";}
function openChronicleDialog(characterId,historyId="",targetId="",editId=""){updateSocietyFields(activeSociety);selectedCharacterId=characterId||selectedCharacterId;const form=document.querySelector("#chronicle-form");form.reset();syncRepFactionOptions();form.elements.targetChronicleId.value=targetId;form.elements.editChronicleId.value=editId;selectedChronicleFile=null;document.querySelector("#chronicle-review").hidden=Boolean(targetId);document.querySelector("#scan-status").textContent=targetId?"Choose a scan to attach to this existing chronicle.":"Scan optional. Enter details below; you can attach a scan later from Chronicle History. Upload now to fill fields automatically.";document.querySelector("#scan-status").className="scan-status";const saveButton=document.querySelector("#save-chronicle");saveButton.disabled=Boolean(targetId);saveButton.textContent=targetId?"Attach scan":"Save chronicle";document.querySelector("#chronicle-dialog .modal-head h2").textContent=targetId?"Attach scan to chronicle":editId?"Edit chronicle":"Record a chronicle";const select=form.elements.characterId;select.innerHTML=activeCharacters().map(c=>`<option value="${esc(c.id)}" ${c.id===selectedCharacterId?"selected":""}>${esc(c.name)}</option>`).join("");if(!activeCharacters().length){alert(`Add a ${societyTitle()} character before recording a chronicle.`);return;}if(historyId){const row=state.sessionHistory.find(item=>item.id===historyId);if(row){form.elements.historyEntryId.value=row.id;form.elements.title.value=row.title;form.elements.datePlayed.value=row.date;form.elements.event.value=row.event||"";form.elements.role.value=/gm|game master/i.test(row.role||"")?"gm":"player";const code=(row.title.match(/(?:#|PFS(?:\(2ed\))?\s*)(\d{1,2}[-–]\d{1,3})/i)||[])[1];if(code)form.elements.scenarioCode.value=code.replace("–","-");}}if(editId){const row=state.chronicles.find(item=>item.id===editId);if(row){form.elements.title.value=row.title||"";form.elements.sheetType.value=row.sheetType||"scenario";form.elements.scenarioCode.value=row.scenarioCode||"";form.elements.chronicleCode.value=row.chronicleCode||"";form.elements.datePlayed.value=row.datePlayed||"";form.elements.event.value=row.event||"";form.elements.role.value=row.role==="gm"?"gm":"player";form.elements.xpEarned.value=Number(row.xpEarned)||0;form.elements.gpGained.value=Number(row.gpGained)||0;form.elements.gpSpent.value=Number(row.gpSpent)||0;form.elements.gpAdjustment.value=Number(row.gpAdjustment)||0;legacyReputation(row).slice(0,3).forEach(([name,amount],index)=>{form.elements[`repFaction${index+1}`].value=PFS2_FACTIONS.includes(name)?name:"";form.elements[`repAmount${index+1}`].value=amount;});syncRepFactionOptions();form.elements.notes.value=row.notes||"";document.querySelector("#chronicle-review").hidden=false;document.querySelector("#scan-kind").textContent=chronicleTypeName(row.sheetType);document.querySelector("#scan-status").textContent="Edit the chronicle values, then save to update this ledger entry.";}}document.querySelector(".rep-adjustments").hidden=activeSociety==="starfinder";document.querySelector("#chronicle-system-note").hidden=activeSociety!=="starfinder";chronicleDialog.showModal();}
