function setStatus(message,type=""){const el=document.querySelector("#scan-status");el.textContent=message;el.className=`scan-status ${type}`;}
function normalizeText(text){return String(text||"").replace(/\r/g,"\n").replace(/[\t ]+/g," ").replace(/\n{3,}/g,"\n\n").trim();}
async function extractPdfText(file){const pdfjs=await import("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs");pdfjs.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs";const buffer=await file.arrayBuffer();const pdf=await pdfjs.getDocument({data:buffer}).promise;let text="";for(let pageNo=1;pageNo<=Math.min(pdf.numPages,6);pageNo++){const page=await pdf.getPage(pageNo);const content=await page.getTextContent();text+=content.items.map(item=>item.str).join(" ")+"\n";}if(text.replace(/\s/g,"").length<40){for(let pageNo=1;pageNo<=Math.min(pdf.numPages,2);pageNo++){const page=await pdf.getPage(pageNo);const viewport=page.getViewport({scale:2});const canvas=document.createElement("canvas");canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext("2d"),viewport}).promise;text+=await ocrBlob(await new Promise(resolve=>canvas.toBlob(resolve,"image/png")));}}return text;}
async function ocrBlob(blob){if(!window.Tesseract)throw new Error("Photo OCR could not load. Check your internet connection or enter the fields by hand.");const result=await window.Tesseract.recognize(blob,"eng",{logger:message=>{if(message.status==="recognizing text")setStatus(`Reading the sheet… ${Math.round((message.progress||0)*100)}%`);}});return result.data.text||"";}
function suggestTitle(text,fileName){const line=(text.match(/(?:Pathfinder Society Scenario|Pathfinder Adventure|Pathfinder Society Quest)[^\n]{0,130}/i)||[])[0];if(line)return line.replace(/\s+/g," ").trim().slice(0,110);return fileName.replace(/\.[^.]+$/,"").replace(/\s*[-–]\s*chronicle.*$/i,"");}
function suggestCode(text){const scenario=(text.match(/(?:Scenario|Quest)\s*#?\s*(\d{1,2}[-–]\d{1,3})/i)||[])[1];const chronicle=(text.match(/Chronicle Code\s*:?\s*([A-Z0-9]{3,8})/i)||[])[1];return {scenarioCode:scenario||"",chronicleCode:chronicle||""};}
function detectSheetType(text){if(/Starting XP|Starting GP|Total XP|GP Spent/i.test(text))return"scenario";if(/Items Sold|Items Bought|Downtime|Reputation Gained/i.test(text))return"adventure";if(/Achievement Point Reward|grants access|This Chronicle Sheet Grants Access/i.test(text))return"boon";return"scenario";}
