function useBoon(id){const boon=state.boons.find(b=>b.id===id);if(!boon||boon.useType!=="limited")return;const left=Math.max(0,(Number(boon.uses)||0)-(Number(boon.used)||0));if(left<=0)return;boon.used=(Number(boon.used)||0)+1;boon.usageLog=[...(boon.usageLog||[]),new Date().toISOString()];saveState();render();}
function resetBoon(id){const boon=state.boons.find(b=>b.id===id);if(!boon||boon.useType!=="limited")return;boon.used=0;boon.usageLog=[];saveState();render();}
async function showPortrait(character){const blob=await fileGet(character.portraitKey);if(!blob){alert("Portrait image is not available on this device yet.");return;}const image=document.querySelector("#portrait-viewer-image"),viewer=document.querySelector("#portrait-viewer"),url=URL.createObjectURL(blob);image.src=url;image.alt=`${character.name} portrait`;document.querySelector("#portrait-viewer-caption").textContent=character.name;viewer.showModal();viewer.dataset.objectUrl=url;}
document.querySelector("#close-portrait-viewer").addEventListener("click",()=>document.querySelector("#portrait-viewer").close());document.querySelector("#portrait-viewer").addEventListener("click",event=>{if(event.target===event.currentTarget)event.currentTarget.close();});document.querySelector("#portrait-viewer").addEventListener("close",event=>{const url=event.currentTarget.dataset.objectUrl;if(url)URL.revokeObjectURL(url);delete event.currentTarget.dataset.objectUrl;document.querySelector("#portrait-viewer-image").removeAttribute("src");});async function openAttachment(key,name){const blob=await fileGet(key);if(!blob){alert("The attachment is not available in this browser.");return;}const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.target="_blank";link.rel="noopener";link.download=name||"chronicle";link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
document.querySelector("#account-button").addEventListener("click",async()=>{if(cloudUser){if(confirm(`Sign out ${cloudUser.email||"of this account"}? Your local browser copy stays here.`)){if(cloudUnsubscribe)cloudUnsubscribe();cloudUnsubscribe=null;await signOut(firebaseAuth);}return;}document.querySelector("#auth-error").hidden=true;document.querySelector("#auth-dialog").showModal();});
document.querySelector("#auth-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=event.submitter,errorBox=document.querySelector("#auth-error"),email=String(form.elements.email.value).trim(),password=String(form.elements.password.value);errorBox.hidden=true;try{if(button?.value==="signUp")await createUserWithEmailAndPassword(firebaseAuth,email,password);else await signInWithEmailAndPassword(firebaseAuth,email,password);document.querySelector("#auth-dialog").close();form.reset();}catch(error){errorBox.textContent=error.message||"Authentication failed.";errorBox.hidden=false;}});
document.querySelector("#use-cloud-data").addEventListener("click",()=>{if(cloudConflictState){applyCloudState(cloudConflictState);writeCloudState(state);}});
